import {getList, refreshCiAttr} from '@/api/device/cmdbciattr'

export default {
  props: ["isShow", "ciId", "ciName", "ciLabel"],
  data() {
    return {
      searchForm: {
        size: 20,
        current: 1
      },
      tableList: [],
      tableHeight: "500px",
      tableLoading: false,
      total: 0,
    }
  },
  mounted() {
    this.searchForm.ciId = this.ciId
    this.getTableList()
  },
  methods: {
    getTableList() {
      this.tableLoading = true
      getList(this.searchForm).then(res => {
        this.tableList = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    search() {
      this.searchForm.current = 1
      this.getTableList()
    },
    restForm() {
      this.searchForm = {
        size: 20,
        current: 1,
        ciId: this.ciId
      }
      this.getTableList()
    },
    refresh() {
      this.tableLoading = true
      refreshCiAttr({
        ciId: this.ciId,
        ciName: this.ciName
      }).then(res => {
        this.$message({
          type: "success",
          message: res.data
        });
        this.search()
      })
    },
    Nindex(index) {
      return index + 1 + (this.searchForm.current - 1) * this.searchForm.size;
    },
  }
}
